mapper.select:
SELECT st.* FROM edu_student st

    st.student_status = 1

        AND st.student_class_id = #{classId}


        AND st.student_grade_level = #{gradeLevel}


        AND st.student_grade = #{grade}



            AND (st.student_owner_user_id IS NULL OR st.student_owner_user_id = #{scope.ownerPredicate})



ORDER BY st.student_id ASC
